#ifndef WS_IO_BUFFER_H
#define WS_IO_BUFFER_H

#include <vector>
#include <atomic>
#include <span>
#include <initializer_list>
#include <string_view>
#include <optional>

namespace ws {

class Buffer {
public:
  Buffer(std::size_t size);
  Buffer(std::span<const std::byte> bytes);
  Buffer(std::initializer_list<std::byte> bytes);
  Buffer(std::string_view str);

  [[nodiscard]] constexpr std::size_t WritableSize() const noexcept;
  [[nodiscard]] constexpr std::size_t ReadableSize() const noexcept;
  [[nodiscard]] constexpr std::span<const std::byte> Peek() const noexcept;
  [[nodiscard]] constexpr std::span<std::byte> ReadableBytes() noexcept;
  [[nodiscard]] constexpr std::string_view ReadableString() const noexcept;
  [[nodiscard]] constexpr std::span<std::byte> WritableBytes() noexcept;

  void Append(std::span<const std::byte> bytes);
  void Append(std::initializer_list<std::byte> bytes);
  void Append(std::string_view str, std::optional<NewLine> newline = {});
  void Append(const void* data, std::size_t size);
  void Append(const Buffer& buf);

  void EnsureWriteableSize(std::size_t size);
  bool HasWritten(std::size_t size) const noexcept;
  std::span<std::byte> Retrieve(std::size_t size);
  void RetrieveUntil(const void* addr);
  std::vector<std::byte> RetrieveAll();
  std::string RetrieveAllToString();
  void Clear();
  bool Empty() const noexcept;

private:
  std::vector<std::byte> buf_;
  std::atomic<std::size_t> read_pos_; 
  std::atomic<std::size_t> write_pos_;
};

}
#endif // WS_IO_BUFFER_H

#ifndef WS_IO_IO_H
#define WS_IO_IO_H

#include <cstddef>
#include <atomic>
#include <memory>

namespace ws {
namespace io {

class IReader {
public:
  virtual ~IReader() = default;
  virtual std::size_t ReadFrom(Buffer& buf) = 0;
};

class IWriter {
public:
  virtual ~IWriter() = default;
  virtual std::size_t WriteTo(Buffer& buf) = 0;
};

class IReadWriter : public IReader, public IWriter {};

class Null : public IReadWriter {
public:
  void WriteTo(Buffer& buf) noexcept override;
  std::size_t ReadFrom(Buffer& buf) noexcept override;
};

class StringStream : public IReadWriter {
public:
  explicit StringStream(std::istream& read, std::ostream& write) noexcept;
  std::size_t WriteTo(Buffer& buf) noexcept override;
  std::size_t ReadFrom(Buffer& buf) noexcept override;

private:
  std::istream& read_; 
  std::ostream& write_; 
};

class FileDescriptor : public IReadWriter {
public:
  explicit FileDescriptor(ws::FileDescriptor read, ws::FileDescriptor write) noexcept;
  std::size_t WriteTo(Buffer& buf) override;
  std::size_t ReadFrom(Buffer& buf) override;

private:
  ws::FileDescriptor read_; 
  ws::FileDescriptor write_; 
};

}
}

#endif // WS_IO_IO_H
